    /// <summary>Card action "Test-BrokerTableValidation". Validates every entry.</summary>
    public static List<ModuleResult> Validate()
    {
        var results = new List<ModuleResult>();
        var brokers = GetBrokerTable();
        var issues = new List<string>();
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var b in brokers)
        {
            if (!seen.Add(b.Name)) issues.Add($"duplicate broker name: {b.Name}");
            if (string.IsNullOrWhiteSpace(b.Url)) issues.Add($"{b.Name}: empty URL");
            else if (!b.Url.StartsWith("https://", StringComparison.OrdinalIgnoreCase)) issues.Add($"{b.Name}: URL not https: {b.Url}");
            if (!ValidMethods.Contains(b.Method)) issues.Add($"{b.Name}: unknown method '{b.Method}'");
            if (!ValidCategories.Contains(b.Category)) issues.Add($"{b.Name}: unknown category '{b.Category}'");
            if (string.IsNullOrWhiteSpace(b.Notes)) issues.Add($"{b.Name}: empty Notes");
        }
        if (issues.Count == 0)
            results.Add(ModuleResult.Pass("BrokerEradicator",
                $"Broker table OK: {brokers.Count} brokers, names unique, all https, methods/categories valid.",
                new { total = brokers.Count }));
        else
            results.Add(ModuleResult.Fail("BrokerEradicator",
                $"Broker table ISSUES ({issues.Count}): " + string.Join("; ", issues.Take(10)),
                issues));
        return results;
    }

    /// <summary>Coverage: totals per method and per category.</summary>
    public static Dictionary<string, object> GetCoverage()
    {
        var brokers = GetBrokerTable();
        return new Dictionary<string, object>
        {
            ["total"] = brokers.Count,
            ["byMethod"] = brokers.GroupBy(b => b.Method).ToDictionary(g => g.Key, g => g.Count()),
            ["byCategory"] = brokers.GroupBy(b => b.Category).ToDictionary(g => g.Key, g => g.Count()),
        };
    }
